package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's periods: each named uniquely on the sheet, from and to a date inclusive, none
 * overlapping. Closing a period fixes, at that moment, each person's due-total for it (the figures
 * as shown then of their claims whose date falls in it that counted by the status they had at the
 * end of its last day) and its own due-total, the sum of theirs. Soft-closing fixes them the same
 * way while claims dated inside it can still change; a soft-closed period can then be closed (fixing
 * them afresh). A steward can reopen a closed or soft-closed period, making its due-total live again.
 */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetRepository sheets;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final ClaimService claimService;
    private final SettingService settings;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetRepository sheets, ClaimRepository claims,
            PersonRepository people, ClaimService claimService, SettingService settings, Audit audit) {
        this.settings = settings;
        this.periods = periods;
        this.sheets = sheets;
        this.claims = claims;
        this.people = people;
        this.claimService = claimService;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        if (to.isBefore(from)) throw new PeriodDatesException();
        // Lock the sheet so two users adding periods at once cannot overlap or share a name.
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        if (periods.existsBySheetIdAndName(sheetId, name)) throw new DuplicatePeriodNameException();
        if (periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new PeriodOverlapException();
        }
        Period saved = periods.saveAndFlush(new Period(sheetId, name, from, to));
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user.strip()
                + " period=" + saved.getName() + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
        return saved;
    }

    /**
     * Make one period per calendar month from the from-date's month to the to-date's month, each from
     * the first to the last day of its month and named yyyy-mm. A month whose name is already a period,
     * or whose days overlap one on the sheet, is left out; the others are still made. A blank date
     * takes the sheet's today.
     */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate fromOrNull, LocalDate toOrNull) {
        // Lock the sheet so two users adding periods at once cannot overlap or share a name.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        LocalDate from = fromOrNull == null ? today : fromOrNull;
        LocalDate to = toOrNull == null ? today : toOrNull;
        if (to.isBefore(from)) throw new PeriodDatesException();
        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) continue;
            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
            existing.add(saved);
            made.add(saved);
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user.strip()
                    + " period=" + saved.getName() + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
        }
        return made;
    }

    @Transactional
    public Period close(String sheetId, String user, Long id) {
        // Lock the sheet so no claim in the period changes while its due-total is fixed.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!settings.mayDo(sheetId, user, "close")) throw new PeriodNotPermittedException();
        if (period.isClosed()) throw new PeriodClosedException();
        return fix(sheetId, user, period, today, false, false);
    }

    @Transactional
    public Period softClose(String sheetId, String user, Long id) {
        // Lock the sheet so no claim in the period changes while its due-total is fixed.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!settings.mayDo(sheetId, user, "close")) throw new PeriodNotPermittedException();
        if (period.isClosed() || period.isSoftClosed()) throw new PeriodClosedException();
        return fix(sheetId, user, period, today, false, true);
    }

    /**
     * Close, as a close by hand would, every open period (not a soft-closed one) whose to-date plus the grace days is before the
     * sheet's today, in order of their to-dates, each audited with auto=yes. The caller holds the sheet's
     * lock, with its new today already set.
     */
    @Transactional
    public void autoClose(String sheetId, String user, LocalDate today, int graceDays) {
        List<Period> due = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
                .sorted(Comparator.comparing(Period::getToDate))
                .toList();
        for (Period period : due) fix(sheetId, user, period, today, true, false);
    }

    /** Close or soft-close the period, fixing each person's due-total for it and its own, and audit it. */
    private Period fix(String sheetId, String user, Period period, LocalDate today, boolean auto, boolean soft) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        // Every person on the sheet gets a figure, 0.00 when none of their claims falls in it.
        Map<Long, BigDecimal> personDues = new LinkedHashMap<>();
        for (Long personId : byId.keySet()) personDues.put(personId, BigDecimal.ZERO.setScale(2));
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !period.contains(claim.getDate()) || !person.countsAt(claim, period.getToDate(), today)) continue;
            BigDecimal figure = claimService.chargedFigureOf(sheetId, person, claim);
            if (figure != null) personDues.merge(person.getId(), figure, BigDecimal::add);
        }
        if (soft) period.softClose(personDues);
        else period.close(personDues);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + user.strip()
                + " period=" + saved.getName() + " total=" + saved.getClosedDueTotal().setScale(2).toPlainString()
                + (auto ? " auto=yes" : ""));
        return saved;
    }

    @Transactional
    public Period reopen(String sheetId, String user, Long id) {
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!settings.mayDo(sheetId, user, "reopen")) throw new PeriodNotPermittedException();
        if (!period.isClosed() && !period.isSoftClosed()) throw new PeriodOpenException();
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user.strip()
                + " period=" + saved.getName());
        return saved;
    }
}
package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;
import java.util.TreeMap;

/**
 * A period of the sheet: a name unique on the sheet, from and to a date, both inclusive. Once
 * closed, its due-total and each person's due-total for it are fixed at what they were when it was
 * closed; reopened, they are live again. Soft-closed, its figures are fixed the same way, but claims
 * dated inside it can still change.
 */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether it is soft-closed: its figures fixed, its claims still free to change. Never with closed. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** The due-total fixed when the period was closed or soft-closed; none while it is open. */
    @Column(name = "closed_due_total", precision = 14, scale = 2)
    private BigDecimal closedDueTotal;

    /** Each person's due-total for it fixed when it was closed, by person id; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_due", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "due_total", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> closedPersonDues = new TreeMap<>();

    protected Period() {}

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public String getName() { return name; }

    public LocalDate getFromDate() { return fromDate; }

    public LocalDate getToDate() { return toDate; }

    public boolean isClosed() { return closed; }

    public boolean isSoftClosed() { return softClosed; }

    public BigDecimal getClosedDueTotal() { return closedDueTotal; }

    public Map<Long, BigDecimal> getClosedPersonDues() { return closedPersonDues; }

    /** Close it, fixing each person's due-total for it and its own, the sum of theirs. */
    public void close(Map<Long, BigDecimal> personDues) {
        fix(personDues);
        this.closed = true;
        this.softClosed = false;
    }

    /** Soft-close it, fixing its figures as a close does while its claims can still change. */
    public void softClose(Map<Long, BigDecimal> personDues) {
        fix(personDues);
        this.softClosed = true;
    }

    private void fix(Map<Long, BigDecimal> personDues) {
        this.closedPersonDues.clear();
        this.closedPersonDues.putAll(personDues);
        this.closedDueTotal = personDues.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen it: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedDueTotal = null;
        this.closedPersonDues.clear();
    }

    /** Whether the date falls in it, both ends inclusive. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether it shares a date with the other dates, both inclusive. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !from.isAfter(toDate);
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the
 * sheet's claimed-total and due-total, each person's at most the sheet's cap in force today; a claim's floor is the one in force on its date, its late percent the one in force on each 30-day boundary; an overdue claim's due has its {@link LateCharge} on top. A change takes a {@link #snapshot} before it alters
 * anything and calls {@link #recordChanges} once it has, which audits, after the change's own
 * lines, a ROLLUP line for each person whose figures (overdue-total included) moved (in the order
 * they were added) and a TOTALS line when the sheet's totals moved.
 */
@Service
public class RollupService {

    /** A person's figures; a null due-total is n/a; the overdue-total is the dues of their overdue claims. */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.compareTo(other.claimed) == 0 && Objects.equals(dueTotal, other.dueTotal)
                    && overdueTotal.compareTo(other.overdueTotal) == 0;
        }
    }

    /** The sheet's figures at a moment: each person's, by id in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
            BigDecimal overdueTotal) {}

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * The sheet's figures now. Locks the sheet until the caller's transaction ends, so no other
     * change on the sheet moves the figures between this snapshot and the one after the change.
     */
    public Snapshot snapshot(String sheetId) {
        Sheet sheet = sheets.findForUpdate(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        LocalDate policyDate = sheet == null ? null : sheet.getPolicyDate();
        Map<String, List<Rate>> ratesByGrade = new LinkedHashMap<>();
        for (Rate rate : rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId)) {
            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
        }
        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<String, LocalDate> datesByNumber = Rounding.datesByNumber(all);
        for (Claim claim : all) {
            if (claim.getStatus().counts()) {
                claimsByPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean fixed = false;
            for (Claim claim : claimsByPerson.getOrDefault(person.getId(), List.of())) {
                if (!person.counts(claim, today)) continue;
                claimed = claimed.add(claim.getAmount());
                if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) fixed = true;
                String grade = person.gradeOn(claim.getDate());
                RoundingMode rounding = Rounding.of(Rounding.basisOf(claim, datesByNumber), policyDate, today);
                // the floor in force on the claim's date, the late percent in force on each 30-day boundary
                BigDecimal floor = sheet == null ? zero() : sheet.floorOn(claim.getDate());
                BigDecimal figure = LateCharge.withCharge(claim,
                        figureOf(claim, ratesByGrade.getOrDefault(grade, List.of()), rounding), today,
                        d -> sheet == null ? zero() : sheet.latePctOn(d), rounding);
                // the floor last, over the figure and its charge; a settled due is frozen, a correction has none
                if (figure != null && claim.getSettledDue() == null && !claim.isCorrection()) figure = figure.max(floor);
                // a due under a grade they had on its date but not today counts like a fixed one
                if (figure != null && today != null && !grade.equals(person.gradeOn(today))) fixed = true;
                // and so does a due under a rate that is not the one in force today
                if (figure != null && today != null && !Rate.inForce(ratesByGrade.getOrDefault(grade, List.of()),
                        claim.getDate()).equals(Rate.inForce(ratesByGrade.getOrDefault(grade, List.of()), today))) fixed = true;
                if (figure != null) due = due.add(figure);
                if (figure != null && LateCharge.isOverdue(claim, today)) overdue = overdue.add(figure);
            }
            // As on screen: n/a when their grade has no rate today and none of the counted claims has a fixed
            // due, nor a due under another grade they had on its date or under a rate not in force today.
            boolean rated = today != null
                    && pctOn(ratesByGrade.getOrDefault(person.gradeOn(today), List.of()), today) != null;
            BigDecimal personDue = fixed || rated ? due : null;
            if (sheet != null) personDue = sheet.capped(personDue);
            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue, overdue));
            claimedTotal = claimedTotal.add(claimed);
            if (personDue != null) dues.add(personDue);
            overdues.add(overdue);
        }
        return new Snapshot(figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
        if (figures.size() < 3) return sum;
        BigDecimal max = figures.stream().max(BigDecimal::compareTo).orElseThrow();
        BigDecimal min = figures.stream().min(BigDecimal::compareTo).orElseThrow();
        return sum.subtract(max).subtract(min);
    }

    /** Audit, once the transaction commits, a SNAPSHOT line of each person's due-total in {@code snapshot}, in the order they were added. */
    public void recordSnapshot(String sheetId, String user, Snapshot snapshot) {
        String by = " sheet=" + sheetId + " by=" + user.strip();
        for (Figures figures : snapshot.people().values()) {
            audit.recordOnCommit("SNAPSHOT" + by + " name=" + figures.name()
                    + " due-total=" + (figures.dueTotal() == null ? "n/a" : money(figures.dueTotal())));
        }
    }

    /** Audit, once the transaction commits, how the sheet's figures moved since {@code before}. */
    public void recordChanges(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        String by = " sheet=" + sheetId + " by=" + user.strip();
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            if (now.sameAs(before.people().get(e.getKey()))) continue;
            audit.recordOnCommit("ROLLUP" + by + " person=" + now.name() + " claimed=" + money(now.claimed())
                    + " due-total=" + (now.dueTotal() == null ? "n/a" : money(now.dueTotal()))
                    + " overdue-total=" + money(now.overdueTotal()));
        }
        if (after.claimedTotal().compareTo(before.claimedTotal()) != 0
                || after.dueTotal().compareTo(before.dueTotal()) != 0
                || after.overdueTotal().compareTo(before.overdueTotal()) != 0) {
            audit.recordOnCommit("TOTALS" + by + " claimed-total=" + money(after.claimedTotal())
                    + " due-total=" + money(after.dueTotal())
                    + " overdue-total=" + money(after.overdueTotal()));
        }
    }

    /**
     * A claim's figure: its settled due, else its stated rate figure, else its rate figure (no floor),
     * rounded as given; null when it has none.
     */
    private static BigDecimal figureOf(Claim claim, List<Rate> rates, RoundingMode rounding) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isBound()) return claim.getStatedDue();
        BigDecimal pct = pctOn(rates, claim.getDate());
        if (pct == null) return null;
        return claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding);
    }

    /** Of one grade's rates, the percent in force on the date, or null. */
    private static BigDecimal pctOn(List<Rate> rates, LocalDate date) {
        return Rate.inForce(rates, date)
                .map(Rate::getPct)
                .orElse(null);
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String money(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}

